 * An event-sourced double-entry ledger: accounts, immutable entries, balances
 * at any point in time, and reversals.
 */
import { ACCOUNT_TYPES, LedgerError, toNormal } from './money.js';

function isNonEmptyString(value) {
  return typeof value === 'string' && value !== '';
}

function isNonNegativeInteger(value) {
  return typeof value === 'number' && Number.isInteger(value) && value >= 0;
}

/** A ledger of accounts and the balanced entries posted against them. */
export class Ledger {
  #accounts = new Map();
  #entries = new Map();
  #order = [];
  #nextSeq = 1;

  /**
   * Open an account.
   *
   * @param {{id: string, name: string, type: string}} account Account to open.
   * @returns {Readonly<{id: string, name: string, type: string}>} The opened account.
   */
  openAccount(account) {
    if (typeof account !== 'object' || account === null) {
      throw new LedgerError('BAD_ACCOUNT', 'account must be an object');
    }
    const { id, name, type } = account;
    if (typeof id !== 'string' || id === '') {
      throw new LedgerError('BAD_ACCOUNT', 'account id must be a non-empty string');
    }
    if (typeof name !== 'string' || name === '') {
      throw new LedgerError('BAD_ACCOUNT', 'account name must be a non-empty string');
    }
    if (!ACCOUNT_TYPES.includes(type)) throw new LedgerError('UNKNOWN_TYPE', `unknown account type: ${type}`);
    if (this.#accounts.has(id)) throw new LedgerError('DUPLICATE_ACCOUNT', `account already exists: ${id}`);
    const record = Object.freeze({ id, name, type });
    this.#accounts.set(id, record);
    return record;
  }

  /** @returns {Array<Readonly<object>>} Accounts in ascending id order. */
  accounts() {
    return [...this.#accounts.keys()].sort().map((id) => this.#accounts.get(id));
  }

  #requireAccount(accountId) {
    const account = this.#accounts.get(accountId);
    if (!account) throw new LedgerError('UNKNOWN_ACCOUNT', `unknown account: ${accountId}`);
    return account;
  }

  #expose(record) {
    return Object.freeze({
      id: record.id,
      at: record.at,
      seq: record.seq,
      memo: record.memo,
      lines: record.lines,
      reverses: record.reverses,
      reversedBy: record.reversedBy,
    });
  }

  /**
   * Internal entry poster shared by post() and reverse().
   *
   * @param {object} entry Raw entry payload.
   * @param {string|null} reversesId Entry id being reversed, if any.
   * @returns {Readonly<object>} The stored entry.
   */
  #post(entry, reversesId) {
    if (typeof entry !== 'object' || entry === null) {
      throw new LedgerError('BAD_ENTRY', 'entry must be an object');
    }
    const { id, at, lines } = entry;
    const memo = entry.memo === undefined ? '' : entry.memo;

    if (!isNonEmptyString(id)) {
      throw new LedgerError('BAD_ENTRY', 'entry id must be a non-empty string');
    }
    if (this.#entries.has(id)) {
      throw new LedgerError('DUPLICATE_ENTRY', `entry already exists: ${id}`);
    }
    if (!isNonNegativeInteger(at)) {
      throw new LedgerError('BAD_TIME', 'entry time must be a non-negative integer');
    }
    if (typeof memo !== 'string') {
      throw new LedgerError('BAD_ENTRY', 'entry memo must be a string');
    }
    if (!Array.isArray(lines) || lines.length < 2) {
      throw new LedgerError('TOO_FEW_LINES', 'entry must have at least two lines');
    }

    const validatedLines = [];
    let sum = 0;
    for (const line of lines) {
      const account = line && line.account;
      const amountCents = line && line.amountCents;
      this.#requireAccount(account);
      if (!Number.isSafeInteger(amountCents)) {
        throw new LedgerError('NOT_INTEGER', 'amountCents must be a safe integer');
      }
      if (amountCents === 0) {
        throw new LedgerError('ZERO_LINE', 'amountCents must not be zero');
      }
      sum += amountCents;
      validatedLines.push(Object.freeze({ account, amountCents }));
    }
    if (sum !== 0) {
      throw new LedgerError('UNBALANCED', 'entry lines must sum to zero');
    }

    let original = null;
    if (reversesId !== null) {
      original = this.#entries.get(reversesId);
      if (at < original.at) {
        throw new LedgerError('BAD_TIME', 'reversal must not precede its entry');
      }
    }

    const seq = this.#nextSeq;
    this.#nextSeq += 1;
    const record = {
      id,
      at,
      seq,
      memo,
      lines: Object.freeze(validatedLines),
      reverses: reversesId,
      reversedBy: null,
    };
    this.#entries.set(id, record);
    this.#order.push(record);
    if (original) {
      original.reversedBy = id;
    }
    return this.#expose(record);
  }

  /**
   * Post a balanced entry.
   *
   * @param {{id: string, at: number, memo?: string, lines: Array<{account: string, amountCents: number}>}} entry Entry to post.
   * @returns {Readonly<object>} The stored entry.
   */
  post(entry) {
    return this.#post(entry, null);
  }

  /**
   * Look up an entry.
   *
   * @param {string} id Entry id.
   * @returns {Readonly<object>|undefined} The entry, if it exists.
   */
  getEntry(id) {
    const record = this.#entries.get(id);
    return record ? this.#expose(record) : undefined;
  }

  #sortedEntries() {
    return [...this.#order].sort((a, b) => (a.at - b.at) || (a.seq - b.seq));
  }

  #checkAsOf(asOf) {
    if (asOf !== Infinity && !isNonNegativeInteger(asOf)) {
      throw new LedgerError('BAD_TIME', 'asOf must be a non-negative integer');
    }
  }

  /**
   * Entries up to a moment, oldest first.
   *
   * @param {{asOf?: number}} [options] Cut-off, inclusive.
   * @returns {Array<Readonly<object>>} Matching entries ordered by time then posting order.
   */
  entries(options = {}) {
    const asOf = options.asOf === undefined ? Infinity : options.asOf;
    this.#checkAsOf(asOf);
    return this.#sortedEntries()
      .filter((record) => record.at <= asOf)
      .map((record) => this.#expose(record));
  }

  /**
   * Debit-positive balance of one account.
   *
   * @param {string} accountId Account to measure.
   * @param {{asOf?: number}} [options] Cut-off, inclusive.
   * @returns {number} Signed balance in cents.
   */
  balance(accountId, options = {}) {
    this.#requireAccount(accountId);
    const asOf = options.asOf === undefined ? Infinity : options.asOf;
    this.#checkAsOf(asOf);
    let total = 0;
    for (const record of this.#order) {
      if (record.at > asOf) continue;
      for (const line of record.lines) {
        if (line.account === accountId) total += line.amountCents;
      }
    }
    return total;
  }

  /**
   * Balance of one account in its own normal direction.
   *
   * @param {string} accountId Account to measure.
   * @param {{asOf?: number}} [options] Cut-off, inclusive.
   * @returns {number} Balance in cents, positive when on the normal side.
   */
  normalBalance(accountId, options = {}) {
    const account = this.#requireAccount(accountId);
    const signed = this.balance(accountId, options);
    return toNormal(account.type, signed);
  }

  /**
   * Debit and credit totals across every account.
   *
   * @param {{asOf?: number}} [options] Cut-off, inclusive.
   * @returns {{debits: number, credits: number, byAccount: Record<string, number>}} Trial balance.
   */
  trialBalance(options = {}) {
    const asOf = options.asOf === undefined ? Infinity : options.asOf;
    this.#checkAsOf(asOf);
    let debits = 0;
    let credits = 0;
    const byAccount = {};
    for (const account of this.accounts()) {
      const value = this.balance(account.id, { asOf });
      byAccount[account.id] = value;
      if (value > 0) debits += value;
      else if (value < 0) credits += -value;
    }
    return { debits, credits, byAccount };
  }

  /**
   * Post the mirror image of an entry.
   *
   * @param {string} entryId Entry to reverse.
   * @param {{id: string, at: number, memo?: string}} options Identity and time of the reversal.
   * @returns {Readonly<object>} The reversing entry.
   */
  reverse(entryId, options) {
    const original = this.#entries.get(entryId);
    if (!original) throw new LedgerError('NOT_FOUND', `unknown entry: ${entryId}`);
    if (original.reverses !== null) throw new LedgerError('REVERSAL_OF_REVERSAL', `entry is itself a reversal: ${entryId}`);
    if (original.reversedBy !== null) throw new LedgerError('ALREADY_REVERSED', `entry already reversed: ${entryId}`);

    const lines = original.lines.map((line) => ({ account: line.account, amountCents: -line.amountCents }));
    const memo = options && options.memo !== undefined ? options.memo : `reversal of ${entryId}`;
    const payload = { id: options && options.id, at: options && options.at, memo, lines };
    return this.#post(payload, entryId);
  }

  /**
   * Every line touching one account inside a window, with a running balance.
   *
   * @param {string} accountId Account to report on.
   * @param {{from?: number, to?: number}} [options] Inclusive window.
   * @returns {Array<{entryId: string, at: number, seq: number, amountCents: number, balanceCents: number}>} Statement rows.
   */
  statement(accountId, options = {}) {
    this.#requireAccount(accountId);
    const from = options.from === undefined ? -Infinity : options.from;
    const to = options.to === undefined ? Infinity : options.to;
    const rows = [];
    let running = 0;
    for (const record of this.#sortedEntries()) {
      for (const line of record.lines) {
        if (line.account !== accountId) continue;
        running += line.amountCents;
        if (record.at >= from && record.at <= to) {
          rows.push({
            entryId: record.id,
            at: record.at,
            seq: record.seq,
            amountCents: line.amountCents,
            balanceCents: running,
          });
        }
      }
    }
    return rows;
  }
}
