  statement(accountId, options = {}) {
    this.#requireAccount(accountId);
    const from = options.from === undefined ? -Infinity : options.from;
    const to = options.to === undefined ? Infinity : options.to;
    const rows = [];
    let running = 0;
    for (const record of this.#sortedEntries()) {
      for (const line of record.lines) {
        if (line.account !== accountId) continue;
        running += line.amountCents;
        if (record.at >= from && record.at <= to) {
          rows.push({
            entryId: record.id,
            at: record.at,
            seq: record.seq,
            amountCents: line.amountCents,
            balanceCents: running,
          });
        }
      }
    }
    return rows;
  }
